// cos_rando_cli - the randomizer's seed generator on the host (docs/RANDOMIZER_PLAN.md step R1.6).
//
//   build/native-mac/cos_rando_cli [options] <seed>...
//
// Generates each seed with pc_rando_generate (pc_rando_gen.h) and writes, per seed, the placement
// JSON (schema format 1, R0.6) and the logs of decision D5 ("WW Random <seed> - Spoiler Log.txt",
// "- Non-Spoiler Log.txt", "- Error Log.txt" on failure), each log followed by the line
// "Generated by SwitchWaker <version>".
//
// Options start at wwrando's defaults (Options()):
//   name=<json>             set one option, as ww_export.py takes them (a value that is not JSON is a
//                           string: sword_mode=Swordless)
//   --options FILE          a JSON object of options, or a placement JSON (its "options"); name=value
//                           pairs are applied after it
//   --permalink P           seed and options from a wwrando permalink (no <seed> then)
//   --out DIR               where the files go (default: the current directory); the placement is
//                           <DIR>/<seed>.json
//   --json PATH             the placement's path instead (one seed only; '-' for stdout)
//   --no-logs               write only the placement
//   --allow-missing-hints   generate without hints (faster; same placement; pc_rando_gen.h)
//   --seed-key KEY          SEED_KEY for do_not_generate_spoiler_log seeds (default: the port's, D2)
//   --sw-version V          the version written into the placement and the log trailer (default dev)
//   --time                  print the generation time of each seed on stderr
//   --quiet                 no line per seed on stdout
//
// Each seed prints "ok <seed> <hash32> <json path>" or "FAIL <seed>: <first error line>".
// Options whose game side is not ready yet (randomize_enemies until R7.4d) are generated here
// (GenRequest::allowNotRuntimeReady); the menu refuses them.
// Exit 0 all generated, 1 a seed failed (wwrando would raise), 3 an option is not supported yet,
// 2 usage or file error.
//
// Built only for the host (native/cmake/executable.cmake), linked against cos_rando_core like the
// unit tests.
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

#include "pc_rando_gen.h"
#include "pc_rando_json.h"
#include "pc_rando_options.h"
#include "pc_rando_seedfile.h"
#include "pc_rando_spoiler.h"
#include "pc_rando_trap.h"

namespace {

int usage(const char* msg) {
    if (msg != nullptr) {
        std::fprintf(stderr, "cos_rando_cli: %s\n", msg);
    }
    std::fprintf(stderr,
                 "usage: cos_rando_cli [--options FILE] [name=<json> ...] [--out DIR | --json PATH] [--no-logs]\n"
                 "                     [--allow-missing-hints] [--seed-key KEY] [--sw-version V] [--time] [--quiet]\n"
                 "                     (<seed>... | --permalink P)\n");
    return 2;
}

bool readFile(const std::string& path, std::string& out) {
    FILE* f = std::fopen(path.c_str(), "rb");
    if (f == nullptr) {
        return false;
    }
    out.clear();
    char buf[65536];
    size_t n;
    while ((n = std::fread(buf, 1, sizeof buf, f)) > 0) {
        out.append(buf, n);
    }
    const bool ok = !std::ferror(f);
    std::fclose(f);
    return ok;
}

bool writeFile(const std::string& path, const std::string& text) {
    if (path == "-") {
        return std::fwrite(text.data(), 1, text.size(), stdout) == text.size();
    }
    FILE* f = std::fopen(path.c_str(), "wb");
    if (f == nullptr) {
        std::fprintf(stderr, "cos_rando_cli: cannot write %s\n", path.c_str());
        return false;
    }
    const bool ok = std::fwrite(text.data(), 1, text.size(), f) == text.size();
    return std::fclose(f) == 0 && ok;
}

std::string firstLine(const std::string& s) {
    const size_t e = s.find('\n');
    return e == std::string::npos ? s : s.substr(0, e);
}

} // namespace

int main(int argc, char** argv) {
    pcr::Json optJson = pcr::Json::object();
    std::vector<std::string> seeds;
    std::string permalink, outDir = ".", jsonPath, version = "dev";
    std::string seedKey = pcr::kSwitchWakerSeedKey;
    bool logs = true, allowMissingHints = false, timing = false, quiet = false, havePermalink = false;

    for (int i = 1; i < argc; i++) {
        const std::string a = argv[i];
        auto value = [&](const char* name) -> const char* {
            if (i + 1 >= argc) {
                std::fprintf(stderr, "cos_rando_cli: %s needs a value\n", name);
                std::exit(2);
            }
            return argv[++i];
        };
        if (a == "--options") {
            const std::string path = value("--options");
            std::string text, err;
            pcr::Json d;
            if (!readFile(path, text) || !pcr::jsonParse(text, &d, &err) || !d.isObject()) {
                std::fprintf(stderr, "cos_rando_cli: cannot read options from %s %s\n", path.c_str(), err.c_str());
                return 2;
            }
            if (d.find("format") != nullptr && d.find("options") != nullptr) {
                d = *d.find("options");
            }
            for (size_t k = 0; k < d.size(); k++) {
                optJson.set(d.keyAt(k), d.at(k));
            }
        } else if (a == "--permalink") {
            permalink = value("--permalink");
            havePermalink = true;
        } else if (a == "--out") {
            outDir = value("--out");
        } else if (a == "--json") {
            jsonPath = value("--json");
        } else if (a == "--no-logs") {
            logs = false;
        } else if (a == "--allow-missing-hints") {
            allowMissingHints = true;
        } else if (a == "--seed-key") {
            seedKey = value("--seed-key");
        } else if (a == "--sw-version") {
            version = value("--sw-version");
        } else if (a == "--time") {
            timing = true;
        } else if (a == "--quiet") {
            quiet = true;
        } else if (a == "-h" || a == "--help") {
            return usage(nullptr);
        } else if (a.size() > 1 && a[0] == '-' && a[1] == '-') {
            return usage(("unknown option " + a).c_str());
        } else if (a.find('=') != std::string::npos && pcr::optionFind(a.substr(0, a.find('=')).c_str()) >= 0) {
            const std::string name = a.substr(0, a.find('='));
            const std::string text = a.substr(a.find('=') + 1);
            pcr::Json v;
            if (!pcr::jsonParse(text, &v, nullptr)) {
                v = pcr::Json::string(text);
            }
            optJson.set(name, v);
        } else if (a.find('=') != std::string::npos) {
            return usage(("unknown wwrando option in " + a).c_str());
        } else {
            seeds.push_back(a);
        }
    }

    pcr::Options opts;
    std::string err;
    if (!pcr::optionsFromJson(optJson, &opts, &err)) {
        return usage(err.c_str());
    }
    if (havePermalink) {
        if (!seeds.empty()) {
            return usage("--permalink takes no <seed>");
        }
        std::string seed;
        const pcr::PermalinkError pe = pcr::decodePermalink(permalink, &seed, &opts);
        if (pe != pcr::PermalinkError::None) {
            std::fprintf(stderr, "cos_rando_cli: bad permalink: %s\n", pcr::permalinkErrorText(pe));
            return 2;
        }
        seeds.push_back(seed);
    }
    if (seeds.empty()) {
        return usage("no seed");
    }
    if (!jsonPath.empty() && seeds.size() != 1) {
        return usage("--json takes one seed");
    }

    int rc = 0;
    for (const std::string& s : seeds) {
        pcr::GenRequest req;
        req.seed = s;
        req.options = opts;
        req.allowMissingHints = allowMissingHints;
        req.allowNotRuntimeReady = true; // R7.2a: options the game does not apply yet (palettes)
        req.seedKey = seedKey.c_str();
        req.version = version;
        pcr::GenResult res;
        const auto t0 = std::chrono::steady_clock::now();
        const bool ok = pcr::generate(req, res);
        const double secs = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
        if (timing) {
            std::fprintf(stderr, "time %s %.3f s\n", res.sanitizedSeed.c_str(), secs);
        }
        const std::string trailer = pcr::logTrailer(version.c_str());
        const std::string name = res.sanitizedSeed.empty() ? s : res.sanitizedSeed;
        if (!ok) {
            std::printf("FAIL %s: %s\n", name.c_str(), firstLine(res.error).c_str());
            std::fflush(stdout);
            if (logs && !res.errorLog.empty()) {
                writeFile(outDir + "/" + pcr::logFileName(name, "Error Log"), res.errorLog + trailer);
            }
            // Files of an earlier successful run of this seed in the same --out would sit next to
            // the error log and look current.
            if (jsonPath.empty()) {
                std::remove((outDir + "/" + name + ".json").c_str());
            }
            if (logs) {
                std::remove((outDir + "/" + pcr::logFileName(name, "Spoiler Log")).c_str());
                std::remove((outDir + "/" + pcr::logFileName(name, "Non-Spoiler Log")).c_str());
            }
            if (rc == 0 || (res.unsupported && rc == 1)) {
                rc = res.unsupported ? 3 : 1;
            }
            continue;
        }
        const std::string path = !jsonPath.empty() ? jsonPath : outDir + "/" + name + ".json";
        if (!writeFile(path, res.placementJson)) {
            return 2;
        }
        if (logs) {
            if (res.spoilerLog.empty()) {
                std::remove((outDir + "/" + pcr::logFileName(name, "Spoiler Log")).c_str());
            } else if (!writeFile(outDir + "/" + pcr::logFileName(name, "Spoiler Log"), res.spoilerLog + trailer)) {
                return 2;
            }
            if (!writeFile(outDir + "/" + pcr::logFileName(name, "Non-Spoiler Log"), res.nonSpoilerLog + trailer)) {
                return 2;
            }
            // A stale error log from an earlier failed run of this seed in the same --out.
            std::remove((outDir + "/" + pcr::logFileName(name, "Error Log")).c_str());
        }
        if (!quiet && path != "-") {
            std::printf("ok %s %08x %s\n", name.c_str(), (unsigned)pc_rando_seed_hash32(res.seed), path.c_str());
            std::fflush(stdout);
        }
    }
    return rc;
}
